FILE = "messi-princess-of-asturias.html"
TITLE = "One of one: Messi wins the Princess of Asturias Award on his own"
TAG = "Flavor Sports"
H1 = "One of one: Messi wins the Princess of Asturias Award on his own"
DEK = "Spain's highest cultural honour has gone to football before, but never to one footballer alone. In Oviedo on Friday night, that changed."
META = "Flavor Sports · 24 Oct 2026 · 4 min read"
LEAD = ("img/sp-messi-wave.jpg", "Messi at the Teatro Campoamor, Oviedo")

BODY = [
("p", "Two weeks after saying goodbye to Argentina, Lionel Messi was back on a stage, this time in a suit. On Friday 23 October 2026, at the Teatro Campoamor in Oviedo, he received the 2026 Princess of Asturias Award for Sports, becoming the first footballer to win it on his own."),
("h2", "The moment", "Handed over by ", "Princess Leonor"),
("img", "img/sp-messi-leonor.jpg", "Princess Leonor presents the award to Messi"),
("p", "The award was presented by Princess Leonor, the heir to the Spanish throne, with King Felipe VI and Queen Letizia in the audience. In her speech she praised the way Messi read the game and made decisions in fractions of a second, always putting the team ahead of himself, and said he had turned the extraordinary into routine."),
("h2", "Why it's history", "The first ", "to win it alone"),
("img", "img/sp-messi-oviedo.jpg", "Messi in Oviedo"),
("p", "Football has been honoured by the Princess of Asturias Awards before, but always as a team or a pair. Brazil's national team won the sports award in 2002, after their fifth World Cup, and Spain's Xavi Hernández and Iker Casillas shared it in 2012. Messi is the first footballer to be recognised by himself. He joins a list of sports winners that includes Serena Williams, Rafael Nadal and Kenya's own Eliud Kipchoge."),
("h2", "Why he won", "More titles ", "than anyone else"),
("img", "img/sp-messi-antonela.jpg", "Messi with his wife, Antonela Roccuzzo"),
("p", "When the jury named him back on 3 June, it called him the player who has won more titles than anyone in the history of football. But it also pointed beyond the trophies, to his humility on the pitch, his commitment to team play and his charity work giving disadvantaged children access to education and healthcare."),
("h2", "The class of 2026", "In good ", "company"),
("img", "img/sp-laureates.jpg", "The 2026 laureates in Oviedo"),
("p", "Messi shared the week with the rest of this year's laureates, among them the musician Patti Smith and Studio Ghibli, the Japanese animation house behind <em>Spirited Away</em> and <em>My Neighbor Totoro</em>, which won the award for Communication and Humanities. Look closely at the class photo and you'll spot a Totoro."),
]

